namespace cells;
table RealImage { path:string; source:string; }
table Outputs { image:RealImage (required); }
root_type Outputs;

{ pkgs, inputs, params }:
# A real fluorescence image of human cell nuclei, fixed by its hash: fetched once
# into the Nix store, never during a run. Moffat et al., Cell 124(6), 2006; image
# by David Root, CC0, from the scikit-image data repository.
let
  image = pkgs.fetchurl {
    url = params.url;
    hash = params.hash;
  };
in
{
  run = ''
    echo "source: ${params.url}"
    echo "hash: ${params.hash}"
    echo "image: ${image} ($(wc -c < ${image}) bytes)"
    printf '{"image": {"path": "%s", "source": "%s"}}' "${image}" "${params.url}" > "$TSUGUMI_OUTPUT"
  '';
}

{
  "language": "bash",
  "inputs": [
    {
      "name": "start"
    }
  ],
  "params": [
    {
      "name": "url",
      "type": "string",
      "data": "https://gitlab.com/scikit-image/data/-/raw/2cdc5ce89b334d28f06a58c9f0ca21aa6992a5ba/AS_09125_050116030001_D03f00d0.tif",
      "nix": true
    },
    {
      "name": "hash",
      "type": "string",
      "data": "sha256-J1G6ZnxAZ8XTCBfP8ASqBvb2KH8c27W4ycalADCMtFY=",
      "nix": true
    }
  ]
}

